#include <iostream>
#include <cstdint>
#include <iomanip>

int main() {
    uint8_t a = 0b00001100; // 12
    uint8_t b = 0b00001010; // 10

    uint8_t and_res = a & b; // 00001000 = 8
    uint8_t or_res  = a | b; // 00001110 = 14
    uint8_t xor_res = a ^ b; // 00000110 = 6
    uint8_t not_a   = static_cast<uint8_t>(~a); // 11110011 = 243

    std::cout << "a & b = " << static_cast<int>(and_res) << "\n";
    std::cout << "a | b = " << static_cast<int>(or_res)  << "\n";
    std::cout << "a ^ b = " << static_cast<int>(xor_res) << "\n";
    std::cout << "~a    = " << static_cast<int>(not_a)   << "\n";

    return 0;
}

#include <iostream>
#include <climits>
#include <iomanip>

// Portable binary display function
void displayBits(unsigned int value) {
    constexpr unsigned int totalBits = CHAR_BIT * sizeof(unsigned int);
    // Construct mask for the MSB
    const unsigned int displayMask = 1u << (totalBits - 1);

    std::cout << std::setw(10) << value << " = ";

    for (unsigned int c = 1; c <= totalBits; ++c) {
        std::cout << ((value & displayMask) ? '1' : '0');
        value <<= 1;

        if (c % 8 == 0) {
            std::cout << ' ';
        }
    }
    std::cout << '\n';
}

int main() {
    unsigned int x = 65000;
    displayBits(x);
    return 0;
}
